import test from "node:test";
import assert from "node:assert/strict";
import { createWarehouseState } from "../src/domain/warehouse.mjs";
import { InMemoryWarehouseRepository } from "../src/infrastructure/in-memory-repository.mjs";
import { WarehouseService } from "../src/application/warehouse-service.mjs";
import { createWarehouseApi } from "../src/api/warehouse-api.mjs";

function reservationOverview(snapshot) {
  const activeReservations = snapshot.reservations.filter((reservation) => reservation.status === "active");
  const expiredReservations = snapshot.reservations.filter((reservation) => reservation.status === "expired");
  return {
    activeCount: activeReservations.length,
    expiredCount: expiredReservations.length,
    reservedUnits: activeReservations.reduce((total, reservation) => {
      return total + reservation.lines.reduce((lineTotal, line) => lineTotal + line.quantity, 0);
    }, 0),
    nextExpiry:
      activeReservations.length === 0
        ? null
        : activeReservations
            .map((reservation) => reservation.expiresAt)
            .reduce((earliest, expiresAt) => (expiresAt < earliest ? expiresAt : earliest))
  };
}

function fixture(initialStock = { A: 8, B: 4 }) {
  const repository = new InMemoryWarehouseRepository(createWarehouseState(initialStock));
  const service = new WarehouseService(repository);
  const api = createWarehouseApi(service);
  return { repository, service, api };
}

test("exposes the reservation lifecycle through the API while preserving existing endpoints", () => {
  const { api } = fixture({ A: 10, B: 5 });
  const now = new Date("2026-08-09T12:00:00Z");

  assert.equal(typeof api.allocateOrder, "function");
  assert.equal(typeof api.restock, "function");
  assert.equal(typeof api.reserveStock, "function");
  assert.equal(typeof api.confirmReservation, "function");
  assert.equal(typeof api.releaseExpired, "function");
  assert.equal(typeof api.listReservations, "function");
  assert.equal(typeof api.getSnapshot, "function");

  const firstReservation = api.reserveStock({
    reservationId: "R-1",
    orderId: "O-1",
    lines: [{ skuId: "A", quantity: 3 }],
    ttlMinutes: 30,
    now
  });

  assert.equal(firstReservation.ok, true);
  assert.deepEqual(firstReservation.reservation, {
    reservationId: "R-1",
    orderId: "O-1",
    lines: [{ skuId: "A", quantity: 3 }],
    ttlMinutes: 30,
    status: "active",
    createdAt: new Date("2026-08-09T12:00:00.000Z"),
    expiresAt: new Date("2026-08-09T12:30:00.000Z")
  });
  assert.equal(api.getSnapshot().stockBySku.A, 7);
  assert.deepEqual(api.listReservations(), [firstReservation.reservation]);
  assert.deepEqual(reservationOverview(api.getSnapshot()), {
    activeCount: 1,
    expiredCount: 0,
    reservedUnits: 3,
    nextExpiry: new Date("2026-08-09T12:30:00Z")
  });

  const confirmation = api.confirmReservation({ reservationId: "R-1" });

  assert.equal(confirmation.ok, true);
  assert.deepEqual(confirmation.order, {
    orderId: "O-1",
    reservationId: "R-1",
    lines: [{ skuId: "A", quantity: 3 }],
    status: "confirmed"
  });
  assert.equal(api.getSnapshot().stockBySku.A, 7);
  assert.deepEqual(api.listReservations().map((reservation) => reservation.status), ["confirmed"]);
  assert.deepEqual(api.getSnapshot().events.map((event) => event.type), [
    "reservation-created",
    "reservation-confirmed"
  ]);

  const secondReservation = api.reserveStock({
    reservationId: "R-2",
    orderId: "O-2",
    lines: [{ skuId: "B", quantity: 2 }],
    ttlMinutes: 15,
    now
  });

  assert.equal(secondReservation.ok, true);
  assert.equal(api.getSnapshot().stockBySku.B, 3);
  assert.deepEqual(reservationOverview(api.getSnapshot()), {
    activeCount: 1,
    expiredCount: 0,
    reservedUnits: 2,
    nextExpiry: new Date("2026-08-09T12:15:00.000Z")
  });

  const release = api.releaseExpired({ now: new Date("2026-08-09T12:20:00Z") });

  assert.equal(release.ok, true);
  assert.equal(release.reservations.length, 1);
  assert.equal(release.reservations[0].reservationId, "R-2");
  assert.equal(release.reservations[0].status, "expired");
  assert.equal(api.getSnapshot().stockBySku.B, 5);
  assert.deepEqual(api.listReservations().map((reservation) => reservation.status), ["confirmed", "expired"]);
  assert.deepEqual(api.getSnapshot().events.map((event) => event.type), [
    "reservation-created",
    "reservation-confirmed",
    "reservation-created",
    "reservation-expired"
  ]);
  assert.deepEqual(reservationOverview(api.getSnapshot()), {
    activeCount: 0,
    expiredCount: 1,
    reservedUnits: 0,
    nextExpiry: null
  });

  const secondRelease = api.releaseExpired({ now: new Date("2026-08-09T13:00:00Z") });

  assert.equal(secondRelease.ok, true);
  assert.equal(secondRelease.reservations.length, 0);
  assert.deepEqual(api.getSnapshot().events.map((event) => event.type), [
    "reservation-created",
    "reservation-confirmed",
    "reservation-created",
    "reservation-expired"
  ]);

  const allocated = api.allocateOrder({
    orderId: "O-3",
    lines: [{ skuId: "A", quantity: 2 }]
  });

  assert.equal(allocated.ok, true);
  assert.equal(api.getSnapshot().stockBySku.A, 5);
  assert.equal(api.restock({ skuId: "B", quantity: 4 }).quantity, 9);
});

