import {
  allocateOrder,
  confirmReservation,
  listReservations,
  releaseExpired,
  reserveStock,
  restock
} from "../domain/warehouse.mjs";

export class WarehouseService {
  constructor(repository) {
    this.repository = repository;
  }

  #loadState() {
    return this.repository.load();
  }

  #saveState(state) {
    this.repository.save(state);
  }

  allocateOrder(input) {
    const state = this.#loadState();
    const result = allocateOrder(state, input);
    if (result.ok) this.#saveState(state);
    return result;
  }

  restock(input) {
    const state = this.#loadState();
    const quantity = restock(state, input);
    this.#saveState(state);
    return quantity;
  }

  reserveStock(input) {
    const state = this.#loadState();
    const result = reserveStock(state, input);
    if (result.ok) this.#saveState(state);
    return result;
  }

  confirmReservation(input) {
    const state = this.#loadState();
    const result = confirmReservation(state, input);
    if (result.ok) this.#saveState(state);
    return result;
  }

  releaseExpired(input) {
    const state = this.#loadState();
    const result = releaseExpired(state, input);
    if (result.ok) this.#saveState(state);
    return result;
  }

  listReservations() {
    const state = this.#loadState();
    return listReservations(state);
  }

  snapshot() {
    return this.#loadState();
  }

  getSnapshot() {
    return this.snapshot();
  }
}

