import test from "node:test";
import assert from "node:assert/strict";

import { createWarehouseState } from "../src/domain/warehouse.mjs";
import { InMemoryWarehouseRepository } from "../src/infrastructure/in-memory-repository.mjs";
import { WarehouseService } from "../src/application/warehouse-service.mjs";
import { createWarehouseApi } from "../src/api/warehouse-api.mjs";

test("keeps the public reservation API independent from service result wrappers", () => {
  const repository = new InMemoryWarehouseRepository(createWarehouseState({ A: 10 }));
  const api = createWarehouseApi(new WarehouseService(repository));

  const reservation = api.reserveStock({
    reservationId: "R-1",
    orderId: "O-1",
    lines: [{ skuId: "A", quantity: 3 }],
    ttlMinutes: 30,
    now: "2026-08-09T12:00:00.000Z"
  });

  assert.equal(reservation.status, "active");
  assert.equal(reservation.expiresAt, "2026-08-09T12:30:00.000Z");

  const confirmed = api.confirmReservation({
    reservationId: "R-1",
    now: "2026-08-09T12:10:00.000Z"
  });
  assert.equal(confirmed.status, "confirmed");

  api.reserveStock({
    reservationId: "R-2",
    orderId: "O-2",
    lines: [{ skuId: "A", quantity: 2 }],
    ttlMinutes: 10,
    now: "2026-08-09T12:00:00.000Z"
  });
  const released = api.releaseExpired({ now: "2026-08-09T12:11:00.000Z" });

  assert.equal(Array.isArray(released), true);
  assert.equal(released.length, 1);
  assert.equal(released[0].reservationId, "R-2");
  assert.deepEqual(api.listReservations().map((item) => item.status).sort(), ["confirmed", "expired"]);
});

