+export function createWarehouseApi(service) {
+  function normalizePublicValue(value) {
+    if (value instanceof Date) return value.toISOString();
+    if (Array.isArray(value)) return value.map(normalizePublicValue);
+    if (value && typeof value === "object") {
+      return Object.fromEntries(Object.entries(value).map(([key, entry]) => [key, normalizePublicValue(entry)]));
+    }
+    return value;
+  }
+
+  return {
+    allocateOrder: (body) => service.allocateOrder(body),
+    reserveStock: (body) => {
+      const result = service.reserveStock(body);
+      return result.ok ? normalizePublicValue(result.reservation) : result;
+    },
+    confirmReservation: (body) => normalizePublicValue(service.confirmReservation(body).reservation),
+    releaseExpired: (body) => normalizePublicValue(service.releaseExpired(body).reservations),
+    listReservations: () => normalizePublicValue(service.listReservations()),
+    restock: (body) => ({ quantity: service.restock(body) }),
+    getSnapshot: () => service.snapshot()
+  };
+}
