+      return result.ok ? normalizePublicValue(result.reservation) : result;
+    },
+    confirmReservation: (body) => normalizePublicValue(service.confirmReservation(body).reservation),
+    releaseExpired: (body) => normalizePublicValue(service.releaseExpired(body).reservations),
+    listReservations: () => normalizePublicValue(service.listReservations()),
+    restock: (body) => ({ quantity: service.restock(body) }),
+    getSnapshot: () => service.snapshot()
+  };
+}
