-export function createWarehouseApi(service) {
-  return {
-    allocateOrder: (body) => service.allocateOrder(body),
-    reserveStock: (body) => service.reserveStock(body),
-    confirmReservation: (body) => service.confirmReservation(body),
-    releaseExpired: (body) => service.releaseExpired(body),
-    listReservations: () => service.listReservations(),
-    restock: (body) => ({ quantity: service.restock(body) }),
-    getSnapshot: () => service.snapshot()
